{"file_path":"src/output.js","content":"function cmp(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

function ser(node, indent) {
  const pad = '  '.repeat(indent + 1)
  const end = '  '.repeat(indent)
  switch (node.t) {
    case 'table': {
      const ks = sortedKeys(node)
      if (!ks.length) return '{}'
      return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${ser(node.map.get(k), indent + 1)}`).join(',\n') + '\n' + end + '}'
    }
    case 'array':
      if (!node.items.length) return '[]'
      return '[\n' + node.items.map((i) => pad + ser(i, indent + 1)).join(',\n') + '\n' + end + ']'
    default:
      return JSON.stringify(node.v)
  }
}

export function toJson(root) {
  return ser(root, 0) + '\n'
}

export function toKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node.t === 'table') {
      for (const k of sortedKeys(node)) {
        const p = path === null ? k : `${path}.${k}`
        lines.push(`${p} ${node.map.get(k).t}`)
        walk(node.map.get(k), p)
      }
    } else if (node.t === 'array') {
      node.items.forEach((it, i) => {
        const p = `${path}[${i}]`
        lines.push(`${p} ${it.t}`)
        walk(it, p)
      })
    }
  }
  walk(root, null)
  return lines.map((l) => l + '\n').join('')
}
"}

